class FfiConverterTypeNoise : FfiConverterRustBuffer<Noise>
{
    public static FfiConverterRustBuffer<Noise> INSTANCE = new FfiConverterTypeNoise();

    public override Noise Read(BigEndianStream stream)
    {
        var value = stream.ReadInt();
        switch (value)
        {
            case 1:
                return new Noise.Ideal(
                );
            case 2:
                return new Noise.Pauli(
                    FfiConverterTypePauliNoiseDistribution.INSTANCE.Read(stream)
                );
            case 3:
                return new Noise.BitFlip(
                    FfiConverterDouble.INSTANCE.Read(stream)
                );
            case 4:
                return new Noise.PhaseFlip(
                    FfiConverterDouble.INSTANCE.Read(stream)
                );
            case 5:
                return new Noise.Depolarizing(
                    FfiConverterDouble.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeNoise.Read()", value));
        }
    }

    public override int AllocationSize(Noise value)
    {
        switch (value)
        {
            case Noise.Ideal variant_value:
                return 4;
            case Noise.Pauli variant_value:
                return 4
                    + FfiConverterTypePauliNoiseDistribution.INSTANCE.AllocationSize(variant_value.@noise);
            case Noise.BitFlip variant_value:
                return 4
                    + FfiConverterDouble.INSTANCE.AllocationSize(variant_value.@p);
            case Noise.PhaseFlip variant_value:
                return 4
                    + FfiConverterDouble.INSTANCE.AllocationSize(variant_value.@p);
            case Noise.Depolarizing variant_value:
                return 4
                    + FfiConverterDouble.INSTANCE.AllocationSize(variant_value.@p);
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeNoise.AllocationSize()", value));
        }
    }

    public override void Write(Noise value, BigEndianStream stream)
    {
        switch (value)
        {
            case Noise.Ideal variant_value:
                stream.WriteInt(1);
                break;
            case Noise.Pauli variant_value:
                stream.WriteInt(2);
                FfiConverterTypePauliNoiseDistribution.INSTANCE.Write(variant_value.@noise, stream);
                break;
            case Noise.BitFlip variant_value:
                stream.WriteInt(3);
                FfiConverterDouble.INSTANCE.Write(variant_value.@p, stream);
                break;
            case Noise.PhaseFlip variant_value:
                stream.WriteInt(4);
                FfiConverterDouble.INSTANCE.Write(variant_value.@p, stream);
                break;
            case Noise.Depolarizing variant_value:
                stream.WriteInt(5);
                FfiConverterDouble.INSTANCE.Write(variant_value.@p, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeNoise.Write()", value));
        }
    }
}







