    QsException(String @Message) : base(@Message) { }

    // Each variant is a nested class


    public class ErrorMessage : QsException
    {
        // Members
        public string @errorText;

        // Constructor
        public ErrorMessage(
                string @errorText) : base(
                "@errorText" + "=" + @errorText)
        {

            this.@errorText = @errorText;
        }
    }



}

